# Pre-tenant lookups (owned by nexora_definer, BYPASSRLS), like the API-key and membership lookups:
#  * the org of an ACTIVE webhook trigger of an ACTIVE org (POST /api/v1/hooks/<id> has no session);
#  * the orgs with due automation work (schedule triggers, elapsed waits/retries, expiring approvals) for the
#    periodic dispatcher. Both return ids only, never tenant rows.
FUNCTIONS_SQL = """
CREATE OR REPLACE FUNCTION nexora_webhook_trigger_org(p_trigger uuid)
RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  SELECT t.org_id
  FROM automation_workflowtrigger t
  JOIN orgs_organization o ON o.id = t.org_id AND o.status = 'active'
  WHERE t.id = p_trigger AND t.type = 'webhook' AND t.is_active
$$;

CREATE OR REPLACE FUNCTION nexora_automation_due_orgs(p_now timestamptz)
RETURNS TABLE(org_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$
  SELECT d.org_id FROM (
    SELECT s.org_id FROM automation_workflowsteprun s
     WHERE s.status IN ('waiting', 'retrying') AND s.resume_at <= p_now
    UNION
    SELECT t.org_id FROM automation_workflowtrigger t
     WHERE t.type = 'schedule' AND t.is_active AND t.next_run_at <= p_now
    UNION
    SELECT a.org_id FROM automation_approvalrequest a
     WHERE a.status = 'pending' AND a.expires_at <= p_now
  ) d
  JOIN orgs_organization o ON o.id = d.org_id AND o.status = 'active'
  ORDER BY d.org_id
$$;

ALTER FUNCTION nexora_webhook_trigger_org(uuid) OWNER TO nexora_definer;
ALTER FUNCTION nexora_automation_due_orgs(timestamptz) OWNER TO nexora_definer;
REVOKE ALL ON FUNCTION nexora_webhook_trigger_org(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION nexora_automation_due_orgs(timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nexora_webhook_trigger_org(uuid) TO nexora_app, nexora_ops;
GRANT EXECUTE ON FUNCTION nexora_automation_due_orgs(timestamptz) TO nexora_app, nexora_ops;
GRANT SELECT ON automation_workflowtrigger, automation_workflowsteprun, automation_approvalrequest TO nexora_definer;
"""

